import heapq

def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """Finds the shortest path in a weighted directed graph using Dijkstra's algorithm."""

    # Priority queue for maintaining the nodes to visit
    queue = []
    heapq.heappush(queue, (0, start))  # (current distance, current node)

    # Store the shortest distance to each node
    distances = {node: float('inf') for node in graph}
    distances[start] = 0

    # Store the path
    previous_nodes = {node: None for node in graph}

    while queue:
        current_distance, current_node = heapq.heappop(queue)

        # If we reached the end node, break the loop
        if current_node == end:
            break

        # If the current distance is greater than the recorded distance, continue
        if current_distance > distances[current_node]:
            continue

        # Check the neighbors of the current node
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # Only consider this new path if it's better
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(queue, (distance, neighbor))

    # Reconstruct the shortest path
    if distances[end] == float('inf'):
        return (float('inf'), [])

    path = []
    current_node = end
    while current_node is not None:
        path.append(current_node)
        current_node = previous_nodes[current_node]
    path.reverse()

    return (distances[end], path)

